import re
src = '''import re


_UNITS = {"h": 3600, "m": 60, "s": 1}
_ORDER = {"h": 3, "m": 2, "s": 1}


def slugify(text):
    """Lowercase *text* and collapse every run of non-alphanumerics to one '-'."""
    return re.sub(r"[^a-z0-9]+", "-", str(text).lower()).strip("-")


def truncate(text, limit, suffix="..."):
    """Shorten *text* to exactly *limit* characters, ending with *suffix*."""
    text = str(text)
    if len(text) <= limit:
        return text
    if limit < len(suffix):
        return suffix[:limit]
    return text[:limit - len(suffix)] + suffix


def parse_duration(text):
    """Parse a duration such as '1h30m' into an integer number of seconds."""
    raw = str(text).strip()
    if not raw:
        raise ValueError("bad duration: %r" % (text,))
    components = re.findall(r"(\\d+)([hms])", raw)
    # The regex must consume the whole string and find at least one component.
    if not components or "".join(n + u for n, u in components) != raw:
        raise ValueError("bad duration: %r" % (text,))
    total = 0
    previous = None
    for number, unit in components:
        if previous is not None and _ORDER[unit] >= _ORDER[previous]:
            # Duplicate unit or units not in descending h, m, s order.
            raise ValueError("bad duration: %r" % (text,))
        previous = unit
        total += int(number) * _UNITS[unit]
    return total


def chunk(items, size):
    """Split *items* into a list of lists of (at most) *size* elements."""
    if size <= 0:
        raise ValueError("chunk size must be positive")
    return [list(items[start:start + size]) for start in range(0, len(items), size)]


def word_count(text):
    """Count whitespace-separated tokens containing at least one alphanumeric."""
    return sum(
        1
        for token in str(text).split()
        if any(char.isalnum() for char in token)
    )
'''
